        raise JsonableError(_("Navigation view already exists."))
    if name is not None and NavigationView.objects.filter(user=user_profile, name=name).exists():
        raise JsonableError(_("Navigation view already exists."))

    do_add_navigation_view(
        user_profile,
        fragment,
        is_pinned,
        name,
    )
    return json_success(request)

